def sse_format(data):
    if isinstance(data, (dict, list)):
        payload = json.dumps(data, ensure_ascii=False)
    else:
        payload = str(data)
    return f"data: {payload}\n\n"

async def upstash_set(key, value):
    if not UPSTASH_REDIS_REST_URL or not UPSTASH_REDIS_REST_TOKEN:
        return
    url = f"{UPSTASH_REDIS_REST_URL}/set/{base64.urlsafe_b64encode(key.encode()).decode()}?value={base64.urlsafe_b64encode(json.dumps(value).encode()).decode()}"
    headers = {"Authorization": f"Bearer {UPSTASH_REDIS_REST_TOKEN}"}
    try:
        await CLIENT.post(url, headers=headers)
    except Exception:
        pass

async def upstash_get(key):
    if not UPSTASH_REDIS_REST_URL or not UPSTASH_REDIS_REST_TOKEN:
        return None
    url = f"{UPSTASH_REDIS_REST_URL}/get/{base64.urlsafe_b64encode(key.encode()).decode()}"
    headers = {"Authorization": f"Bearer {UPSTASH_REDIS_REST_TOKEN}"}
    try:
        r = await CLIENT.get(url, headers=headers)
        if r.status_code == 200:
            body = r.json()
            if body and isinstance(body, dict) and "result" in body and body["result"] is not None:
                try:
                    return json.loads(base64.urlsafe_b64decode(body["result"]).decode())
                except Exception:
                    return body["result"]
    except Exception:
        return None
    return None

async def upstash_search_index(docs):
    if not UPSTASH_SEARCH_REST_URL or not UPSTASH_SEARCH_REST_TOKEN:
        return
    headers = {"Authorization": f"Bearer {UPSTASH_SEARCH_REST_TOKEN}", "Content-Type": "application/json"}
    data = {"documents": docs}
    try:
        await CLIENT.post(f"{UPSTASH_SEARCH_REST_URL}/v1/documents", headers=headers, content=json.dumps(data))
    except Exception:
        pass

async def exa_search(query, num_results=25, include_domains=None):
    if not EXA_API_KEY:
        return []
    url = ""
    headers = {"Content-Type": "application/json", "x-api-key": EXA_API_KEY}
    payload = {"query": query, "numResults": num_results}
    if include_domains:
        payload["includeDomains"] = include_domains
    try:
        r = await CLIENT.post(url, headers=headers, content=json.dumps(payload))
        if r.status_code == 200:
            data = r.json()
            results = data.get("results", []) or data.get("documents", [])
            out = []
            for it in results:
                u = it.get("url") or it.get("source_url") or it.get("id")
                t = it.get("title") or ""
                s = it.get("text") or it.get("snippet") or ""
                if u:
                    out.append({"url": u, "title": t, "snippet": s})
            return out
    except Exception:
        return []
    return []

async def http_get_text(url):
    try:
        r = await CLIENT.get(url, headers={"User-Agent": "Mozilla/5.0"})
        if r.status_code == 200:
            ct = r.headers.get("content-type", "")
            if "text" in ct or "json" in ct or "xml" in ct:
                return r.text
    except Exception:
        return ""
    return ""

def normalize_messages_seed(doc_text):
    content = doc_text.strip()
    content = re.sub(r"\s+", " ", content)
    return content[:20000]

async def cerebras_chat(model, messages, max_tokens=4096, temperature=0.7, top_p=0.9, reasoning_effort=None):
    if not CEREBRAS_API_KEY:
        return ""
    url = ""
    headers = {"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type": "application/json"}
    payload = {"model": model, "messages": messages, "max_completion_tokens": max_tokens, "temperature": temperature, "top_p": top_p, "stream": False}
    if reasoning_effort is not None:
        payload["reasoning_effort"] = reasoning_effort
    try:
        r = await CLIENT.post(url, headers=headers, content=json.dumps(payload))
        if r.status_code == 200:
            data = r.json()
            ch = data.get("choices", [])
            if ch:
                return ch[0].get("message", {}).get("content", "") or ""
    except Exception:
        return ""
    return ""

