async def anthropic_claude(messages, model="claude-3-opus-20240229", max_tokens=4096, temperature=0.7):
    if not ANTHROPIC_API_KEY:
        return ""
    url = ""
    headers = {"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "Content-Type": "application/json"}
    sys_msg = ""
    user_msgs = []
    for m in messages:
        if m["role"] == "system":
            sys_msg = m["content"]
        elif m["role"] in ["user", "assistant"]:
            user_msgs.append({"role": m["role"], "content": m["content"]})
    payload = {"model": model, "max_tokens": max_tokens, "temperature": temperature, "system": sys_msg, "messages": user_msgs}
    try:
        r = await CLIENT.post(url, headers=headers, content=json.dumps(payload))
        if r.status_code == 200:
            data = r.json()
            c = data.get("content", [])
            if c and isinstance(c, list):
                parts = []
                for part in c:
                    if part.get("type") == "text":
                        parts.append(part.get("text", ""))
                return "\n".join(parts)
    except Exception:
        return ""
    return ""

async def gemini_generate(messages, model="models/gemini-2.5-pro", temperature=0.7, top_p=0.9, max_output_tokens=4096):
    if not GOOGLE_API_KEY:
        return ""
    url = f""
    sys_msg = ""
    content_parts = []
    for m in messages:
        if m["role"] == "system":
            sys_msg = m["content"]
        elif m["role"] == "user":
            content_parts.append({"role": "user", "parts": [{"text": m["content"]}]})
        elif m["role"] == "assistant":
            content_parts.append({"role": "model", "parts": [{"text": m["content"]}]})
    if sys_msg:
        content_parts.insert(0, {"role": "user", "parts": [{"text": f"System instruction: {sys_msg}"}]})
    payload = {"contents": content_parts, "generationConfig": {"temperature": temperature, "topP": top_p, "maxOutputTokens": max_output_tokens}}
    headers = {"Content-Type": "application/json"}
    try:
        r = await CLIENT.post(url, headers=headers, content=json.dumps(payload))
        if r.status_code == 200:
            data = r.json()
            cands = data.get("candidates", [])
            if cands:
                parts = cands[0].get("content", {}).get("parts", [])
                texts = []
                for p in parts:
                    if "text" in p:
                        texts.append(p["text"])
                return "\n".join(texts)
    except Exception:
        return ""
    return ""

