def continue_prompt_tail(text, tail_chars=2000):
    tail = text[-tail_chars:] if len(text) > tail_chars else text
    return "Continue EXACTLY from after this tail without repeating any part. Resume mid-sentence if needed.\n\n" + tail + "\n\nContinue now:"

async def plan_topics(seed_text):
    sysm = "Extract 30 diverse, high-recall search queries and a topic outline for exhaustive research. Output JSON with keys: queries[], outline[]."
    msgs = [{"role": "system", "content": sysm}, {"role": "user", "content": seed_text}]
    tasks = []
    tasks.append(asyncio.create_task(cerebras_chat("qwen-3-235b-a22b-instruct-2507", msgs, max_tokens=4000, temperature=0.2, top_p=0.3)))
    tasks.append(asyncio.create_task(cerebras_chat("qwen-3-235b-a22b-thinking-2507", msgs, max_tokens=4000, temperature=0.4, top_p=0.4)))
    tasks.append(asyncio.create_task(cerebras_chat("gpt-oss-120b", msgs, max_tokens=4000, temperature=0.3, top_p=0.5, reasoning_effort="medium")))
    tasks.append(asyncio.create_task(openai_chat_gpt5(msgs, model="gpt-5", max_tokens=3500, temperature=0.2, top_p=0.4)))
    tasks.append(asyncio.create_task(anthropic_claude(msgs, model="claude-3-opus-20240229", max_tokens=3500, temperature=0.2)))
    tasks.append(asyncio.create_task(gemini_generate(msgs, model="models/gemini-2.5-pro", max_output_tokens=3500, temperature=0.2, top_p=0.4)))
    tasks.append(asyncio.create_task(xai_grok(msgs, model="grok-4", max_tokens=3500, temperature=0.2, top_p=0.4)))
    outs = await asyncio.gather(*tasks, return_exceptions=True)
    text = "\n".join([o for o in outs if isinstance(o, str)])
    try:
        m = re.search(r"\{.*\}", text, re.S)
        if m:
            j = json.loads(m.group(0))
            queries = list(dict.fromkeys([q.strip() for q in j.get("queries", []) if isinstance(q, str)]))[:100]
            outline = [s for s in j.get("outline", []) if isinstance(s, str)]
            if queries and outline:
                return queries, outline
    except Exception:
        pass
    raw = re.findall(r"[-•]\s*(.+)", text)
    queries = []
    for it in raw:
        if 3 < len(it) < 180:
            if "?" in it or " vs " in it or "analysis" in it.lower() or "impact" in it.lower():
                queries.append(it.strip())
    queries = list(dict.fromkeys(queries))[:60]
    outline = ["Executive Summary", "Background", "Methods", "Findings", "Discussion", "Conclusion", "References"]
    if not queries:
        queries = [seed_text[:120]]
    return queries, outline

async def gather_sources(queries, max_per_query=25, total_cap=1000):
    urls = []
    for q in queries:
        batch = await exa_search(q, num_results=max_per_query)
        for it in batch:
            u = it["url"]
            urls.append(u)
        if len(urls) >= total_cap:
            break
    urls = list(dict.fromkeys(urls))[:total_cap]
    return urls

async def fetch_contents(urls, max_concurrent=20, per_doc_char_cap=120000):
    sem = asyncio.Semaphore(max_concurrent)
    out = {}
    async def one(u):
        async with sem:
            t = await http_get_text(u)
            if t:
                out[u] = t[:per_doc_char_cap]
    tasks = [asyncio.create_task(one(u)) for u in urls]
    await asyncio.gather(*tasks, return_exceptions=True)
    docs = [{"id": hashlib.sha256(u.encode()).hexdigest(), "text": out[u], "metadata": {"url": u}} for u in out]
    if docs:
        await upstash_search_index([{"id": d["id"], "text": d["text"][:1000], "metadata": d["metadata"]} for d in docs])
    return docs

async def summarize_doc_multi(doc_text, url_hint):
    sysm = "Summarize with key facts, dates, figures, and claims; extract bibliography candidates; output markdown with sections."
    msgs = [{"role": "system", "content": sysm}, {"role": "user", "content": doc_text[:16000] + f"\n\nSource: {url_hint}"}]
    tasks = []
    tasks.append(asyncio.create_task(anthropic_claude(msgs, "claude-3-opus-20240229", 1800, 0.3)))
    tasks.append(asyncio.create_task(gemini_generate(msgs, "models/gemini-2.5-pro", 1800, 0.3, 0.5)))
    tasks.append(asyncio.create_task(openai_chat_gpt5(msgs, "gpt-5", 1800, 0.3, 0.5)))
    tasks.append(asyncio.create_task(xai_grok(msgs, "grok-4", 1800, 0.3, 0.5)))
    tasks.append(asyncio.create_task(cerebras_chat("gpt-oss-120b", msgs, 1800, 0.3, 0.5, "low")))
    outs = await asyncio.gather(*tasks, return_exceptions=True)
    merged = "\n\n".join([o for o in outs if isinstance(o, str)])
    return merged

async def compose_long_report(seed_outline, doc_summaries, target_chars=500000):
    sysm = "Compose a comprehensive research report from provided section plans and evidence summaries. Use academic tone, headings, tables, and references. Do not repeat. Maintain continuity."
    seed = "# Outline\n" + "\n".join([f"- {s}" for s in seed_outline]) + "\n\n# Evidence Summaries\n" + "\n\n---\n\n".join(doc_summaries[:200])
    msgs = [{"role": "system", "content": sysm}, {"role": "user", "content": seed}]
    full = ""
    order = [
        {"model": "qwen-3-235b-a22b-thinking-2507", "type": "cerebras", "max": 32000, "t": 0.5, "p": 0.6, "r": None},
        {"model": "gpt-oss-120b", "type": "cerebras", "max": 48000, "t": 0.6, "p": 0.7, "r": "medium"},
        {"model": "qwen-3-235b-a22b-instruct-2507", "type": "cerebras", "max": 20000, "t": 0.3, "p": 0.4, "r": None},
        {"model": "gpt-5", "type": "openai", "max": 36000, "t": 0.4, "p": 0.5, "r": None},
        {"model": "claude-3-opus-20240229", "type": "anthropic", "max": 36000, "t": 0.4, "p": None, "r": None},
        {"model": "models/gemini-2.5-pro", "type": "gemini", "max": 36000, "t": 0.4, "p": 0.5, "r": None},
        {"model": "grok-4", "type": "xai", "max": 36000, "t": 0.5, "p": 0.6, "r": None},
    ]
    async def run_one(step, cont=False):
        nonlocal msgs
        local_msgs = list(msgs)
        if cont:
            cp = continue_prompt_tail(full, 2000)
            local_msgs.append({"role": "user", "content": cp})
        if step["type"] == "cerebras":
            return await cerebras_chat(step["model"], local_msgs, step["max"], step["t"], step["p"], step["r"])
        if step["type"] == "openai":
            return await openai_chat_gpt5(local_msgs, step["model"], step["max"], step["t"], step["p"])
        if step["type"] == "anthropic":
            return await anthropic_claude(local_msgs, step["model"], step["max"], step["t"])
        if step["type"] == "gemini":
            return await gemini_generate(local_msgs, step["model"], step["t"], step["p"], step["max"])
        if step["type"] == "xai":
            return await xai_grok(local_msgs, step["model"], step["max"], step["t"], step["p"])
        return ""
    for i, step in enumerate(order):
        out = await run_one(step, cont=(i > 0))
        full += out
        msgs.append({"role": "assistant", "content": out})
        if len(full) >= target_chars:
            return full
    while len(full) < target_chars:
        for step in order:
            out = await run_one(step, cont=True)
            full += out
            msgs.append({"role": "assistant", "content": out})
            if len(full) >= target_chars:
                break
    return full

async def research_job(job_id, seed_text, url_hint=None, target_chars=500000, max_sources=1000):
    STATE[job_id] = {"status": "starting", "started_at": now_ts(), "progress": 0}
    await upstash_set(f"job:{job_id}:state", STATE[job_id])
    queries, outline = await plan_topics(seed_text)
    STATE[job_id] = {"status": "searching", "started_at": STATE[job_id]["started_at"], "progress": 5, "queries": len(queries)}
    await upstash_set(f"job:{job_id}:state", STATE[job_id])
    urls = await gather_sources(queries, max_per_query=25, total_cap=max_sources)
    STATE[job_id] = {"status": "fetching", "started_at": STATE[job_id]["started_at"], "progress": 15, "urls": len(urls)}
    await upstash_set(f"job:{job_id}:state", STATE[job_id])
    docs = await fetch_contents(urls, max_concurrent=20, per_doc_char_cap=120000)
    STATE[job_id]["progress"] = 30
    await upstash_set(f"job:{job_id}:state", STATE[job_id])
    doc_summaries = []
    batch = 0
    for d in docs[:200]:
        s = await summarize_doc_multi(d["text"], d["metadata"]["url"])
        doc_summaries.append(s)
        batch += 1
        if batch % 10 == 0:
            STATE[job_id]["progress"] = min(70, 30 + int(40 * batch / max(1, min(200, len(docs)))))
            await upstash_set(f"job:{job_id}:state", STATE[job_id])
    STATE[job_id]["status"] = "composing"
    await upstash_set(f"job:{job_id}:state", STATE[job_id])
    final_report = await compose_long_report(outline, doc_summaries, target_chars=target_chars)
    references = []
    for u in urls[:2000]:
        references.append(f"- {u}")
    report_md = "# Research Report\n\n" + final_report + "\n\n# References\n\n" + "\n".join(references)
    RESULTS[job_id] = {"report.md": report_md, "sources.json": json.dumps({"queries": queries, "urls": urls}, ensure_ascii=False)}
    STATE[job_id]["status"] = "done"
    STATE[job_id]["progress"] = 100
    STATE[job_id]["finished_at"] = now_ts()
    await upstash_set(f"job:{job_id}:state", STATE[job_id])

@app.post("/research/start")
async def research_start(file: UploadFile = File(None), url: str = Form(None), target_chars: int = Form(500000), max_sources: int = Form(1000)):
    if not (file or url):
        raise HTTPException(status_code=400, detail="input required")
    seed = ""
    url_hint = None
    if file:
        seed = (await file.read()).decode(errors="ignore")
    if url and not seed:
        url_hint = url
        seed = await http_get_text(url)
    if not seed:
        raise HTTPException(status_code=400, detail="empty input")
    job_id = uuid.uuid4().hex
    JOBS[job_id] = {"created_at": now_ts()}
    asyncio.create_task(research_job(job_id, normalize_messages_seed(seed), url_hint=url_hint, target_chars=target_chars, max_sources=max_sources))
    return {"job_id": job_id}

@app.get("/research/status/{job_id}")
async def research_status(job_id: str):
    s = STATE.get(job_id)
    if not s:
        s = await upstash_get(f"job:{job_id}:state")
    if not s:
        raise HTTPException(status_code=404, detail="job not found")
    return s

@app.get("/research/stream/{job_id}")
async def research_stream(job_id: str):
    async def gen():
        last = None
        while True:
            s = STATE.get(job_id)
            if not s:
                s = await upstash_get(f"job:{job_id}:state")
            if s != last and s is not None:
                last = s
                yield sse_format(s)
            if s and s.get("status") == "done":
                break
            await asyncio.sleep(1.0)
    return StreamingResponse(gen(), media_type="text/event-stream")

@app.get("/download/{job_id}.zip")
async def download_zip(job_id: str):
    files = RESULTS.get(job_id)
    if not files:
        raise HTTPException(status_code=404, detail="not ready")
    mem = io.BytesIO()
    with zipfile.ZipFile(mem, mode="w", compression=zipfile.ZIP_DEFLATED) as z:
        for name, content in files.items():
            z.writestr(name, content)
    mem.seek(0)
    return StreamingResponse(mem, media_type="application/zip", headers={"Content-Disposition": f'attachment; filename="{job_id}.zip"'})

@app.get("/")
async def root():
    try:
        with open("index.html", "r", encoding="utf-8") as f:
            html = f.read()
        return HTMLResponse(html)
    except Exception:
        return HTMLResponse("<!doctype html><html><body>OK</body></html>")

def run():
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("PORT", "8000")))

if __name__ == "__main__":
    run()
