<script>
const $ = (id)=>document.getElementById(id);
const log = (t)=>{$('log').textContent += t + "\n";$('log').scrollTop = $('log').scrollHeight};
let currentJob = null;
let sse = null;

function setProgress(pct){
  pct = Math.max(0, Math.min(100, Math.floor(pct||0)));
  $('bar').firstElementChild.style.width = pct + '%';
  $('pText').textContent = pct + '%';
}

function fmtTs(ts){
  if(!ts){return '–'}
  try{ return new Date(ts*1000).toLocaleString() }catch(e){ return '–' }
}

async function startResearch(){
  const f = $('file').files[0];
  const u = $('url').value.trim();
  const chars = parseInt($('chars').value||"500000",10);
  const sources = parseInt($('sources').value||"1000",10);
  if(!f && !u){ alert('Adj meg fájlt vagy URL-t.'); return; }
  const fd = new FormData();
  if(f){ fd.append('file', f); }
  if(u){ fd.append('url', u); }
  fd.append('target_chars', String(chars));
  fd.append('max_sources', String(sources));
  $('progressWrap').style.display = 'flex';
  setProgress(0);
  $('status').textContent = 'indítás';
  $('jobId').textContent = '–';
  $('started').textContent = '–';
  $('finished').textContent = '–';
  $('btnDownload').disabled = true;
  $('log').textContent = '';

  const r = await fetch('/research/start', { method:'POST', body: fd });
  if(!r.ok){
    const j = await r.json().catch(()=>({}));
    log('Hiba: ' + (j.detail || ('HTTP '+r.status)));
    return;
  }
  const j = await r.json();
  currentJob = j.job_id;
  $('jobId').textContent = currentJob;
  log('Kutatás elindítva: ' + currentJob);
  startSSE(currentJob);
}

function startSSE(jobId){
  if(sse){ try{sse.close()}catch(e){} sse = null; }
  sse = new EventSource('/research/stream/' + encodeURIComponent(jobId));
  sse.onmessage = (ev)=>{
    try{
      const data = JSON.parse(ev.data);
      $('status').textContent = data.status || '–';
      $('progress').textContent = (data.progress!=null? data.progress+'%' : '–');
      if(data.started_at){ $('started').textContent = fmtTs(data.started_at); }
      if(data.finished_at){ $('finished').textContent = fmtTs(data.finished_at); }
      if(data.progress!=null){ setProgress(data.progress); }
      log('Állapot: ' + (data.status||'–') + ' ' + (data.progress!=null? data.progress+'%':'')); 
      if(data.status === 'done'){
        $('btnDownload').disabled = false;
        sse.close();
      }
    }catch(e){
      log('SSE parse hiba: ' + e.message);
    }
  };
  sse.onerror = ()=>{
    log('SSE kapcsolat hiba, újrapróbálkozás 2s múlva…');
    setTimeout(()=>startSSE(jobId), 2000);
    try{sse.close()}catch(e){}
  };
}

$('btnStart').addEventListener('click', (e)=>{e.preventDefault(); startResearch().catch(err=>log('Hiba: '+err.message));});
$('btnDownload').addEventListener('click', ()=>{
  if(!currentJob){ return; }
  const href = '/download/' + encodeURIComponent(currentJob) + '.zip';
  const a = document.createElement('a');
  a.href = href;
  a.download = currentJob + '.zip';
  document.body.appendChild(a);
  a.click();
  a.remove();
});
</script>
