const std = @import("std");

const JobState = struct {
    status: []const u8,
    progress: u8,
    started_at: i64,
    finished_at: i64,
    queries_count: usize,
    urls_count: usize,
};

const JobResult = struct {
    report: []u8,
    sources_json: []u8,
};

const Job = struct {
    id: []const u8,
    state: JobState,
    result: ?JobResult,
};

var gpa_state = std.heap.GeneralPurposeAllocator(.{}){};
const galloc = gpa_state.allocator();

const Header = std.http.Header;
const Request = std.http.Server.Request;
const Response = std.http.Server.Response;

const CerebrasCfg = struct {
    api_key: []const u8,
};
const OpenAIcfg = struct {
    api_key: []const u8,
};
const AnthropicCfg = struct {
    api_key: []const u8,
};
const GeminiCfg = struct {
    api_key: []const u8,
};
const XAIcfg = struct {
    api_key: []const u8,
};
const ExaCfg = struct {
    api_key: []const u8,
};

const Providers = struct {
    cerebras: ?CerebrasCfg,
    openai: ?OpenAIcfg,
    anthropic: ?AnthropicCfg,
    gemini: ?GeminiCfg,
    xai: ?XAIcfg,
    exa: ?ExaCfg,
};

const JobsMap = std.StringHashMap(*Job);
var jobs = JobsMap.init(galloc);

fn nowTs() i64 {
    return @as(i64, @intCast(std.time.timestamp()));
}

fn writeAll(w: anytype, s: []const u8) !void {
    var off: usize = 0;
    while (off < s.len) {
        const n = try w.write(s[off..]);
        off += n;
    }
}

fn jsonEscape(alloc: std.mem.Allocator, s: []const u8) ![]u8 {
    var buf = std.ArrayList(u8).init(alloc);
    var i: usize = 0;
    while (i < s.len) {
        const c = s[i];
        switch (c) {
            '"' => try buf.appendSlice("\\\""),
            '\\' => try buf.appendSlice("\\\\"),
            '\n' => try buf.appendSlice("\\n"),
            '\r' => try buf.appendSlice("\\r"),
            '\t' => try buf.appendSlice("\\t"),
            else => try buf.append(c),
        }
        i += 1;
    }
    return buf.toOwnedSlice();
}

fn httpClient() std.http.Client {
    return .{
        .allocator = galloc,
        .config = .{
            .ca_bundle = .{ .system = {} },
            .connect_timeout_ms = 10000,
            .tls = .{
                .enable = true,
                .sni = true,
            },
        },
    };
}

fn httpPostJson(host: []const u8, port: u16, scheme_tls: bool, path: []const u8, headers_extra: []const Header, body: []const u8) ![]u8 {
    var client = httpClient();
    defer client.deinit();

    var req = try client.request(.POST, .{ .host = host, .port = port, .protocol = if (scheme_tls) .tls else .plain }, .{
        .target = path,
        .headers = .{},
    });
    defer req.deinit();

    try req.headers.append(.{ .name = "content-type", .value = "application/json" });
    for (headers_extra) |h| try req.headers.append(h);
    try req.start();
    try req.writeAll(body);
    try req.finish();
    try req.wait();

    if (req.response.status != .ok and req.response.status != .created and req.response.status != .accepted) {
        return error.UnexpectedStatus;
    }

    var bytes = std.ArrayList(u8).init(galloc);
    const rdr = req.reader();
    var buf: [16 * 1024]u8 = undefined;
    while (true) {
        const n = try rdr.read(&buf);
        if (n == 0) break;
        try bytes.appendSlice(buf[0..n]);
    }
    return bytes.toOwnedSlice();
}

fn httpGetText(url: []const u8) ![]u8 {
    if (!std.mem.startsWith(u8, url, "http")) return error.UnsupportedScheme;
    var parsed = try std.Uri.parse(url);
    const tls = std.mem.eql(u8, parsed.scheme.?, "https");
    const host = parsed.host.?;
    const port: u16 = if (parsed.port) |p| p else if (tls) 443 else 80;
    var path_buf = std.ArrayList(u8).init(galloc);
    defer path_buf.deinit();
    try path_buf.append('/');
    if (parsed.path) |p| {
        if (p.len > 0) {
            try path_buf.resize(0);
            try path_buf.append('/');
            try path_buf.appendSlice(p);
        }
    }
    if (parsed.query) |q| {
        try path_buf.append('?');
        try path_buf.appendSlice(q);
    }
    const path = try path_buf.toOwnedSlice();

    var client = httpClient();
    defer client.deinit();

    var req = try client.request(.GET, .{ .host = host, .port = port, .protocol = if (tls) .tls else .plain }, .{
        .target = path,
        .headers = .{},
    });
    defer req.deinit();

    try req.start();
    try req.finish();
    try req.wait();

    if (req.response.status != .ok) return error.UnexpectedStatus;

    var out = std.ArrayList(u8).init(galloc);
    const rdr = req.reader();
    var buf: [16 * 1024]u8 = undefined;
    while (true) {
        const n = try rdr.read(&buf);
        if (n == 0) break;
        try out.appendSlice(buf[0..n]);
    }
    return out.toOwnedSlice();
}

fn exaSearch(exa: ExaCfg, query: []const u8, num_results: usize) ![]u8 {
    var body = std.ArrayList(u8).init(galloc);
    defer body.deinit();
    try body.appendSlice("{\"query\":\"");
    const esc = try jsonEscape(galloc, query);
    defer galloc.free(esc);
    try body.appendSlice(esc);
    try body.appendSlice("\",\"numResults\":");
    var buf = try std.fmt.allocPrint(galloc, "{}", .{num_results});
    defer galloc.free(buf);
    try body.appendSlice(buf);
    try body.appendSlice("}");

    const headers_extra = [_]Header{
        .{ .name = "x-api-key", .value = exa.api_key },
    };
    return try httpPostJson("api.exa.ai", 443, true, "/search", headers_extra[0..], body.items);
}

fn cerebrasChat(c: CerebrasCfg, model: []const u8, messages_json: []const u8, max_tokens: usize, temperature: f32, top_p: f32, add_reasoning: bool) ![]u8 {
    var body = std.ArrayList(u8).init(galloc);
    defer body.deinit();
    try body.appendSlice("{\"model\":\"");
    try body.appendSlice(model);
    try body.appendSlice("\",\"messages\":");
    try body.appendSlice(messages_json);
    try body.appendSlice(",\"max_completion_tokens\":");
    var mt = try std.fmt.allocPrint(galloc, "{}", .{max_tokens});
    defer galloc.free(mt);
    try body.appendSlice(mt);
    try body.appendSlice(",\"temperature\":");
