fn geminiMapContents(alloc: std.mem.Allocator, system_text: []const u8, dialog_json: []const u8) ![]u8 {
    var out = std.ArrayList(u8).init(alloc);
    defer out.deinit();
    try out.appendSlice("[");
    if (system_text.len > 0) {
        const sys_esc = try jsonEscape(alloc, system_text);
        defer alloc.free(sys_esc);
        try out.appendSlice("{\"role\":\"user\",\"parts\":[{\"text\":\"System instruction: ");
        try out.appendSlice(sys_esc);
        try out.appendSlice("\"}]}");
    }
    var i: usize = 0;
    var it = std.json.Scanner.initComplete(dialog_json);
    var first = (system_text.len == 0);
    while (true) {
        const tok = it.next();
        if (tok == .end_of_document) break;
        if (tok == .object_begin) {
            var role: []const u8 = "";
            var content: []const u8 = "";
            while (true) {
                const k = it.next();
                if (k == .object_end) break;
                if (k != .string) {
                    _ = it.next();
                    continue;
                }
                const key = it.string;
                const sep = it.next();
                if (std.mem.eql(u8, key, "role") and sep == .string) {
                    role = it.string;
                } else if (std.mem.eql(u8, key, "content") and sep == .string) {
                    content = it.string;
                } else {
                    _ = it.next();
                }
            }
            if (role.len > 0 and content.len > 0) {
                if (!first) try out.appendSlice(",");
                first = false;
                const role_map = if (std.mem.eql(u8, role, "assistant")) "model" else "user";
                try out.appendSlice("{\"role\":\"");
                try out.appendSlice(role_map);
                try out.appendSlice("\",\"parts\":[{\"text\":\"");
                const esc = try jsonEscape(alloc, content);
                defer alloc.free(esc);
                try out.appendSlice(esc);
                try out.appendSlice("\"}]}");
                i += 1;
            }
        }
    }
    try out.appendSlice("]");
    return out.toOwnedSlice();
}

fn parseMultipart(alloc: std.mem.Allocator, body: []const u8, content_type: []const u8) !std.StringHashMap([]u8) {
    var out = std.StringHashMap([]u8).init(alloc);
    const bpos = std.mem.indexOf(u8, content_type, "boundary=");
    if (bpos == null) return error.InvalidMultipart;
    const boundary = content_type[bpos.? + 9 ..];
    var fullb = std.ArrayList(u8).init(alloc);
    defer fullb.deinit();
    try fullb.appendSlice("--");
    try fullb.appendSlice(boundary);
    const delim = try fullb.toOwnedSlice();
    var idx: usize = 0;
    while (true) {
        const start = std.mem.indexOfPos(u8, body, idx, delim);
        if (start == null) break;
        var part_start = start.? + delim.len;
        if (part_start + 2 <= body.len and std.mem.eql(u8, body[part_start .. part_start + 2], "\r\n")) part_start += 2;
        if (part_start + 2 <= body.len and std.mem.eql(u8, body[part_start .. part_start + 2], "--")) break;
        const header_end = std.mem.indexOfPos(u8, body, part_start, "\r\n\r\n") orelse break;
        const headers_bytes = body[part_start .. header_end];
        const content_start = header_end + 4;
        const next = std.mem.indexOfPos(u8, body, content_start, delim) orelse body.len;
        var name: []const u8 = "";
        var disp_line_end = std.mem.indexOf(u8, headers_bytes, "\r\n") orelse headers_bytes.len;
        const disp_line = headers_bytes[0..disp_line_end];
        const nm_pos = std.mem.indexOf(u8, disp_line, "name=\"") orelse disp_line.len;
        if (nm_pos < disp_line.len) {
            const rest = disp_line[nm_pos + 6 ..];
            const q = std.mem.indexOf(u8, rest, "\"") orelse rest.len;
            name = rest[0..q];
        }
        if (name.len > 0) {
            const part_content = body[content_start .. next - 2];
            var val = try alloc.alloc(u8, part_content.len);
            std.mem.copy(u8, val, part_content);
            try out.put(name, val);
        }
        idx = next;
    }
    return out;
}

fn urlencodedToMap(alloc: std.mem.Allocator, body: []const u8) !std.StringHashMap([]u8) {
    var out = std.StringHashMap([]u8).init(alloc);
    var it = std.mem.splitScalar(u8, body, '&');
    while (it.next()) |pair| {
        var kv = std.mem.splitScalar(u8, pair, '=');
        const k = kv.next() orelse continue;
        const v = kv.next() orelse "";
        const kd = try std.Uri.percentDecode(alloc, k);
        defer alloc.free(kd);
        const vd = try std.Uri.percentDecode(alloc, v);
        try out.put(kd, vd);
    }
    return out;
}

fn gatherSources(exa: ?ExaCfg, queries: [][]const u8, max_per_query: usize, total_cap: usize) !std.ArrayList([]u8) {
    var urls = std.ArrayList([]u8).init(galloc);
    if (exa == null) return urls;
    var seen = std.StringHashMap(void).init(galloc);
    for (queries) |q| {
        const res = exaSearch(exa.?, q, max_per_query) catch continue;
        var scanner = std.json.Scanner.initComplete(res);
        while (true) {
            const tok = scanner.next();
            if (tok == .end_of_document) break;
            if (tok == .object_begin) {
                var url: []const u8 = "";
                var title: []const u8 = "";
                var snippet: []const u8 = "";
                while (true) {
                    const k = scanner.next();
                    if (k == .object_end) break;
                    if (k != .string) {
                        _ = scanner.next();
                        continue;
                    }
                    const key = scanner.string;
                    const sep = scanner.next();
                    if (std.mem.eql(u8, key, "url") and sep == .string) {
                        url = scanner.string;
                    } else if (std.mem.eql(u8, key, "title") and sep == .string) {
                        title = scanner.string;
                    } else if (std.mem.eql(u8, key, "text") and sep == .string) {
                        snippet = scanner.string;
                    } else if (std.mem.eql(u8, key, "results") and sep == .array_begin) {
                    } else {
                        _ = scanner.next();
                    }
                }
                if (url.len > 0) {
                    if (!seen.contains(url)) {
                        _ = try seen.put(url, {});
                        const cp = try std.mem.alloc(u8, url.len);
                        std.mem.copy(u8, cp, url);
                        try urls.append(cp);
                        if (urls.items.len >= total_cap) break;
                    }
                }
            }
        }
        if (urls.items.len >= total_cap) break;
    }
    return urls;
}

fn fetchDocs(urls: [][]const u8, per_doc_cap: usize) !std.ArrayList([]u8) {
    var docs = std.ArrayList([]u8).init(galloc);
    for (urls) |u| {
        const txt = httpGetText(u) catch continue;
        const n = if (txt.len > per_doc_cap) per_doc_cap else txt.len;
        var cp = try std.mem.alloc(u8, n);
        std.mem.copy(u8, cp, txt[0..n]);
        try docs.append(cp);
        galloc.free(txt);
    }
    return docs;
}

fn summarizeDocAll(p: Providers, doc: []const u8, url_hint: []const u8) []u8 {
    const sys = "Summarize with key facts, dates, figures, and claims; extract bibliography candidates; output markdown with sections.";
    var messages = messagesJsonSystemUser(galloc, sys, doc) catch return doc;
    defer galloc.free(messages);

    var merged = std.ArrayList(u8).init(galloc);

    if (p.anthropic) |a| {
        const out = anthropicChat(a, "claude-3-opus-20240229", sys, messages, 1800, 0.3) catch null;
        if (out) |o| { _ = merged.appendSlice(o) catch {}; _ = merged.appendSlice("\n\n") catch {}; galloc.free(o); }
    }
    if (p.gemini) |g| {
        const mapped = geminiMapContents(galloc, sys, messages) catch null;
        if (mapped) |m| {
            const out = geminiGenerate(g, "models/gemini-2.5-pro", m, 0.3, 0.5, 1800) catch null;
            if (out) |o| { _ = merged.appendSlice(o) catch {}; _ = merged.appendSlice("\n\n") catch {}; galloc.free(o); }
            galloc.free(m);
        }
    }
    if (p.openai) |oai| {
        const out = openaiChat(oai, "gpt-5", messages, 1800, 0.3, 0.5) catch null;
        if (out) |o| { _ = merged.appendSlice(o) catch {}; _ = merged.appendSlice("\n\n") catch {}; galloc.free(o); }
    }
    if (p.xai) |x| {
        const out = xaiChat(x, "grok-4", messages, 1800, 0.3, 0.5) catch null;
        if (out) |o| { _ = merged.appendSlice(o) catch {}; _ = merged.appendSlice("\n\n") catch {}; galloc.free(o); }
    }
    if (p.cerebras) |cb| {
        const out1 = cerebrasChat(cb, "gpt-oss-120b", messages, 1800, 0.3, 0.5, false) catch null;
        if (out1) |o| { _ = merged.appendSlice(o) catch {}; _ = merged.appendSlice("\n\n") catch {}; galloc.free(o); }
    }

    return merged.toOwnedSlice() catch doc;
}

fn composeReport(p: Providers, outline: [][]const u8, summaries: [][]const u8, target_chars: usize) []u8 {
    var seed = std.ArrayList(u8).init(galloc);
    for (outline) |s| {
        _ = seed.appendSlice("- ") catch {};
        _ = seed.appendSlice(s) catch {};
        _ = seed.appendSlice("\n") catch {};
    }
    _ = seed.appendSlice("\n") catch {};
    for (summaries) |sm| {
        _ = seed.appendSlice("\n---\n\n") catch {};
        _ = seed.appendSlice(sm) catch {};
    }
    const sys = "Compose a comprehensive research report from provided section plans and evidence summaries. Use academic tone, headings, tables, and references. Do not repeat. Maintain continuity.";
    var messages = messagesJsonSystemUser(galloc, sys, seed.items) catch return seed.toOwnedSlice() catch seed.items;
    defer galloc.free(messages);
    var full = std.ArrayList(u8).init(galloc);

    if (p.cerebras) |cb| {
        const out = cerebrasChat(cb, "qwen-3-235b-a22b-thinking-2507", messages, 32000, 0.5, 0.6, false) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    messages = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;

    if (p.cerebras) |cb2| {
        const out = cerebrasChat(cb2, "gpt-oss-120b", messages, 48000, 0.6, 0.7, true) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    messages = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;

    if (p.cerebras) |cb3| {
        const out = cerebrasChat(cb3, "qwen-3-235b-a22b-instruct-2507", messages, 20000, 0.3, 0.4, false) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    messages = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;

    if (p.openai) |oai| {
        const out = openaiChat(oai, "gpt-5", messages, 36000, 0.4, 0.5) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    messages = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;

    if (p.anthropic) |a| {
        const out = anthropicChat(a, "claude-3-opus-20240229", sys, messages, 36000, 0.4) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    messages = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;

    if (p.gemini) |g| {
        const mapped = geminiMapContents(galloc, sys, messages) catch null;
        if (mapped) |m| {
            const out = geminiGenerate(g, "models/gemini-2.5-pro", m, 0.4, 0.5, 36000) catch null;
            if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
            galloc.free(m);
        }
    }
    messages = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;

    if (p.xai) |x| {
        const out = xaiChat(x, "grok-4", messages, 36000, 0.5, 0.6) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }

    while (full.items.len < target_chars) {
        const cont = continueTailPrompt(galloc, full.items, 2000) catch break;
        defer galloc.free(cont);
        messages = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;
        var m2 = messagesJsonSystemUser(galloc, sys, cont) catch messages;
        defer galloc.free(m2);
        if (p.cerebras) |cb| {
            const out = cerebrasChat(cb, "gpt-oss-120b", m2, 36000, 0.5, 0.6, true) catch null;
            if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
        } else break;
        if (full.items.len >= target_chars) break;
    }
    return full.toOwnedSlice() catch full.items;
}

fn deriveQueriesOutline(alloc: std.mem.Allocator, seed: []const u8) !struct { queries: [][]u8, outline: [][]u8 } {
    var queries = std.ArrayList([]u8).init(alloc);
    var outline = std.ArrayList([]u8).init(alloc);
    var it = std.mem.tokenizeAny(u8, seed, " .,;:\n\r\t");
    var seen = std.StringHashMap(void).init(alloc);
    while (it.next()) |tok| {
        if (tok.len > 5 and tok.len < 64) {
            if (!seen.contains(tok)) {
                var cp = try std.mem.alloc(u8, tok.len);
                std.mem.copy(u8, cp, tok);
                _ = try seen.put(cp, {});
                try queries.append(cp);
                if (queries.items.len >= 30) break;
            }
        }
    }
    try outline.append(try std.mem.dupe(alloc, u8, "Executive Summary"));
    try outline.append(try std.mem.dupe(alloc, u8, "Background"));
    try outline.append(try std.mem.dupe(alloc, u8, "Methods"));
    try outline.append(try std.mem.dupe(alloc, u8, "Findings"));
    try outline.append(try std.mem.dupe(alloc, u8, "Discussion"));
    try outline.append(try std.mem.dupe(alloc, u8, "Conclusion"));
    try outline.append(try std.mem.dupe(alloc, u8, "References"));
    return .{ .queries = queries.toOwnedSlice(), .outline = outline.toOwnedSlice() };
}

fn runJob(id: []const u8, seed: []const u8, url_hint_opt: ?[]const u8, target_chars: usize, max_sources: usize, prov: Providers) void {
    var st = JobState{ .status = "starting", .progress = 0, .started_at = nowTs(), .finished_at = 0, .queries_count = 0, .urls_count = 0 };
    if (jobs.get(id)) |jp| jp.*.state = st;

    const deriv = deriveQueriesOutline(galloc, seed) catch {
        if (jobs.get(id)) |jp| {
            jp.*.state.status = "error";
            jp.*.state.finished_at = nowTs();
        }
        return;
    };
    st.status = "searching";
    st.progress = 5;
    st.queries_count = deriv.queries.len;
    if (jobs.get(id)) |jp| jp.*.state = st;

    const urls = gatherSources(prov.exa, deriv.queries, 25, max_sources) catch std.ArrayList([]u8).init(galloc);
    st.status = "fetching";
    st.progress = 15;
    st.urls_count = urls.items.len;
    if (jobs.get(id)) |jp| jp.*.state = st;

    const docs = fetchDocs(urls.items, 120000) catch std.ArrayList([]u8).init(galloc);
    st.progress = 30;
    if (jobs.get(id)) |jp| jp.*.state = st;

    var summaries = std.ArrayList([]u8).init(galloc);
    var count: usize = 0;
    const cap = if (docs.items.len < 200) docs.items.len else 200;
    while (count < cap) : (count += 1) {
        const s = summarizeDocAll(prov, docs.items[count], if (count < urls.items.len) urls.items[count] else "");
        _ = summaries.append(s) catch {};
        const p = 30 + @min(40, @as(u8, @intCast((count * 40) / @max(1, cap))));
        st.progress = p;
        if (jobs.get(id)) |jp| jp.*.state = st;
    }

    st.status = "composing";
    if (jobs.get(id)) |jp| jp.*.state = st;

    const report = composeReport(prov, deriv.outline, summaries.items, target_chars);
    var refs = std.ArrayList(u8).init(galloc);
    _ = refs.appendSlice("{\"queries\":[") catch {};
    for (deriv.queries, 0..) |q, qi| {
        if (qi > 0) _ = refs.appendSlice(",") catch {};
        const esc = jsonEscape(galloc, q) catch q;
        _ = refs.appendSlice("\"") catch {};
        _ = refs.appendSlice(esc) catch {};
        _ = refs.appendSlice("\"") catch {};
        if (esc.ptr != q.ptr) galloc.free(esc);
    }
    _ = refs.appendSlice("],\"urls\":[") catch {};
    for (urls.items, 0..) |u, ui| {
        if (ui > 0) _ = refs.appendSlice(",") catch {};
        const escu = jsonEscape(galloc, u) catch u;
        _ = refs.appendSlice("\"") catch {};
        _ = refs.appendSlice(escu) catch {};
        _ = refs.appendSlice("\"") catch {};
        if (escu.ptr != u.ptr) galloc.free(escu);
    }
    _ = refs.appendSlice("]}") catch {};
    const sources_json = refs.toOwnedSlice() catch refs.items;

    var prefix = std.ArrayList(u8).init(galloc);
    _ = prefix.appendSlice("# Research Report\n\n") catch {};
    const report_md = blk: {
        _ = prefix.appendSlice(report) catch {};
        _ = prefix.appendSlice("\n\n# References\n\n") catch {};
        for (urls.items) |u| {
            _ = prefix.appendSlice("- ") catch {};
            _ = prefix.appendSlice(u) catch {};
            _ = prefix.appendSlice("\n") catch {};
        }
        break :blk prefix.toOwnedSlice() catch prefix.items;
    };

    if (jobs.get(id)) |jp| {
        jp.*.result = .{ .report = report_md, .sources_json = sources_json };
        jp.*.state.status = "done";
        jp.*.state.progress = 100;
        jp.*.state.finished_at = nowTs();
    }
}

fn handleRoot(res: *Response) !void {
    var file = std.fs.cwd().openFile("index.html", .{}) catch {
        res.status = .ok;
        try res.headers.append("content-type", "text/html; charset=utf-8");
        try res.do();
        try writeAll(res, "<!doctype html><html><body>jadedlight</body></html>");
        return;
    };
    defer file.close();
    var st = try file.stat();
    var data = try galloc.alloc(u8, @intCast(st.size));
    _ = try file.readAll(data);
    res.status = .ok;
    try res.headers.append("content-type", "text/html; charset=utf-8");
    try res.do();
    try writeAll(res, data);
    galloc.free(data);
}

fn handleStart(req: *Request, res: *Response, prov: Providers) !void {
    var body = try req.reader().readAllAlloc(galloc, 50 * 1024 * 1024);
    defer galloc.free(body);
    const ct = req.headers.getFirstValue("content-type") orelse "";

    var seed_text: []u8 = "";
    var url_hint: []u8 = "";
    var target_chars: usize = 500000;
    var max_sources: usize = 1000;

    if (std.mem.startsWith(u8, ct, "multipart/form-data")) {
        var mp = try parseMultipart(galloc, body, ct);
        defer {
            var it = mp.iterator();
            while (it.next()) |e| galloc.free(e.value_ptr.*);
            mp.deinit();
        }
        if (mp.get("file")) |v| {
            seed_text = try std.mem.dupe(galloc, u8, v);
        }
        if (mp.get("url")) |v| {
            url_hint = try std.mem.dupe(galloc, u8, v);
        }
        if (mp.get("target_chars")) |v| {
            target_chars = std.fmt.parseInt(usize, v, 10) catch target_chars;
        }
        if (mp.get("max_sources")) |v| {
            max_sources = std.fmt.parseInt(usize, v, 10) catch max_sources;
        }
    } else if (std.mem.startsWith(u8, ct, "application/x-www-form-urlencoded")) {
        var fm = try urlencodedToMap(galloc, body);
        defer {
            var it = fm.iterator();
            while (it.next()) |e| galloc.free(e.value_ptr.*);
            fm.deinit();
        }
        if (fm.get("url")) |v| url_hint = try std.mem.dupe(galloc, u8, v);
        if (fm.get("target_chars")) |v| target_chars = std.fmt.parseInt(usize, v, 10) catch target_chars;
        if (fm.get("max_sources")) |v| max_sources = std.fmt.parseInt(usize, v, 10) catch max_sources;
    } else {
        res.status = .bad_request;
        try res.do();
        return;
    }

    if (seed_text.len == 0 and url_hint.len > 0) {
        const fetched = httpGetText(url_hint) catch "";
        if (fetched.len > 0) seed_text = try std.mem.dupe(galloc, u8, fetched);
        if (fetched.len > 0) galloc.free(fetched);
    }
    if (seed_text.len == 0 and url_hint.len == 0) {
        res.status = .bad_request;
        try res.headers.append("content-type", "application/json");
        try res.do();
        try writeAll(res, "{\"detail\":\"input required\"}");
        return;
    }

    var norm = seed_text;
    if (norm.len > 20000) {
        const cp = try galloc.alloc(u8, 20000);
        std.mem.copy(u8, cp, norm[0..20000]);
        norm = cp;
    }

    const id = std.fmt.allocPrint(galloc, "{s}", .{std.fmt.fmtSliceHex(std.crypto.random.bytesTo(u8, 16) catch &[_]u8{})}) catch blk: {
        const fallback = "job";
        break :blk try std.mem.dupe(galloc, u8, fallback);
    };

    var job = try galloc.create(Job);
    job.* = .{
        .id = id,
        .state = .{ .status = "queued", .progress = 0, .started_at = nowTs(), .finished_at = 0, .queries_count = 0, .urls_count = 0 },
        .result = null,
    };
    try jobs.put(id, job);

    const prov_captured = prov;
    _ = std.Thread.spawn(.{}, struct {
        fn f(ctx: struct { id: []const u8, seed: []const u8, url_hint: ?[]const u8, target: usize, maxs: usize, p: Providers }) void {
            runJob(ctx.id, ctx.seed, ctx.url_hint, ctx.target, ctx.maxs, ctx.p);
        }
    }.f, .{ .id = id, .seed = norm, .url_hint = if (url_hint.len > 0) url_hint else null, .target = target_chars, .maxs = max_sources, .p = prov_captured }) catch {};

    res.status = .ok;
    try res.headers.append("content-type", "application/json; charset=utf-8");
    try res.do();
    try writeAll(res, "{\"job_id\":\"");
    try writeAll(res, id);
    try writeAll(res, "\"}");
}

fn handleStatus(req: *Request, res: *Response) !void {
    const path = req.head.target;
    const base = "/research/status/";
    if (path.len <= base.len) {
        res.status = .bad_request;
        try res.do();
        return;
    }
    const job_id = path[base.len..];
    const j = jobs.get(job_id) orelse {
        res.status = .not_found;
        try res.do();
        return;
    };
    res.status = .ok;
    try res.headers.append("content-type", "application/json; charset=utf-8");
    try res.do();
    var buf = std.ArrayList(u8).init(galloc);
    try buf.appendSlice("{\"status\":\"");
    try buf.appendSlice(j.*.state.status);
    try buf.appendSlice("\",\"progress\":");
    try buf.writer().print("{}", .{j.*.state.progress});
    try buf.appendSlice(",\"started_at\":");
    try buf.writer().print("{}", .{j.*.state.started_at});
    try buf.appendSlice(",\"finished_at\":");
    try buf.writer().print("{}", .{j.*.state.finished_at});
    try buf.appendSlice(",\"queries\":");
    try buf.writer().print("{}", .{j.*.state.queries_count});
    try buf.appendSlice(",\"urls\":");
    try buf.writer().print("{}", .{j.*.state.urls_count});
    try buf.appendSlice("}");
    const out = try buf.toOwnedSlice();
    defer galloc.free(out);
    try writeAll(res, out);
}

fn handleSSE(req: *Request, res: *Response) !void {
    const path = req.head.target;
    const base = "/research/stream/";
    if (path.len <= base.len) {
        res.status = .bad_request;
        try res.do();
        return;
    }
    const job_id = path[base.len..];
    const j = jobs.get(job_id) orelse {
        res.status = .not_found;
        try res.do();
        return;
    };
    res.status = .ok;
    try res.headers.append("content-type", "text/event-stream");
    try res.headers.append("cache-control", "no-cache");
    try res.headers.append("connection", "keep-alive");
    try res.do();

    var last_status: []const u8 = "";
    while (true) {
        const s = j.*.state;
        var payload = std.ArrayList(u8).init(galloc);
        try payload.appendSlice("data: ");
        var json = std.ArrayList(u8).init(galloc);
        try json.appendSlice("{\"status\":\"");
        try json.appendSlice(s.status);
        try json.appendSlice("\",\"progress\":");
        try json.writer().print("{}", .{s.progress});
        try json.appendSlice(",\"started_at\":");
        try json.writer().print("{}", .{s.started_at});
        try json.appendSlice(",\"finished_at\":");
        try json.writer().print("{}", .{s.finished_at});
        try json.appendSlice("}");
        const js = try json.toOwnedSlice();
        defer galloc.free(js);
        try payload.appendSlice(js);
        try payload.appendSlice("\n\n");
        const pl = try payload.toOwnedSlice();
        defer galloc.free(pl);
        try writeAll(res, pl);
        if (std.mem.eql(u8, s.status, "done")) break;
        std.time.sleep(1_000_000_000);
    }
}

fn handleDownload(req: *Request, res: *Response) !void {
    const path = req.head.target;
    const base = "/download/";
    if (!std.mem.startsWith(u8, path, base) or !std.mem.endsWith(u8, path, ".zip")) {
        res.status = .bad_request;
        try res.do();
        return;
    }
    const name_with_ext = path[base.len..];
    const job_id = name_with_ext[0 .. name_with_ext.len - 4];
    const j = jobs.get(job_id) orelse {
        res.status = .not_found;
        try res.do();
        return;
    };
    if (j.*.result == null) {
        res.status = .not_found;
        try res.do();
        return;
    }

    var mem = std.ArrayList(u8).init(galloc);
    var w = std.io.fixedBufferStream(try mem.addManyAsSlice(0, 0));
    var aw = w.writer();

    var zip = std.zip.ArchiveWriter.init(galloc, aw);
    defer zip.deinit();

    {
        var e = try zip.createFile("report.md", .{});
        try e.writeAll(j.*.result.?.report);
        try e.finish();
    }
    {
        var e2 = try zip.createFile("sources.json", .{});
        try e2.writeAll(j.*.result.?.sources_json);
        try e2.finish();
    }
    try zip.finish();

    const out = mem.toOwnedSlice() catch mem.items;

    res.status = .ok;
    try res.headers.append("content-type", "application/zip");
    try res.headers.append("content-disposition", "attachment; filename=\"report.zip\"");
    try res.do();
    try writeAll(res, out);
    galloc.free(out);
}

pub fn main() !void {
    var env = std.process.env_map;
    const cb_key = env.get("CEREBRAS_API_KEY") orelse "";
    const oa_key = env.get("OPENAI_API_KEY") orelse "";
    const an_key = env.get("ANTHROPIC_API_KEY") orelse "";
    const go_key = env.get("GOOGLE_API_KEY") orelse "";
    const xa_key = env.get("XAI_API_KEY") orelse "";
    const ex_key = env.get("EXA_API_KEY") orelse "";
    const providers = Providers{
        .cerebras = if (cb_key.len > 0) .{ .api_key = cb_key } else null,
        .openai = if (oa_key.len > 0) .{ .api_key = oa_key } else null,
        .anthropic = if (an_key.len > 0) .{ .api_key = an_key } else null,
        .gemini = if (go_key.len > 0) .{ .api_key = go_key } else null,
        .xai = if (xa_key.len > 0) .{ .api_key = xa_key } else null,
        .exa = if (ex_key.len > 0) .{ .api_key = ex_key } else null,
    };

    var server = std.http.Server.init(galloc, .{ .reuse_port = true });
    defer server.deinit();

    const host = "0.0.0.0";
    const port: u16 = blk: {
        const env_port = std.process.getEnvVarOwned(galloc, "PORT") catch null;
        if (env_port) |p| {
            defer galloc.free(p);
            break :blk std.fmt.parseInt(u16, p, 10) catch 8000;
        } else break :blk 8000;
    };
    try server.listen(.{ .address = .{ .any = .{} }, .port = port });

    while (true) {
        var conn = try server.accept();
        std.Thread.spawn(.{}, handleConn, .{ &conn, providers }) catch {};
    }
}

fn handleConn(conn: *std.http.Server.Connection, providers: Providers) void {
    defer conn.deinit();
    var req = conn.reader();
    var res = conn.writer();
    while (true) {
        var r = std.http.Server.Request{ .connection = conn.*, .reader = req };
        var s = std.http.Server.Response{ .writer = res };
        if (r.readHead() catch return) {
            const path = r.head.target;
            if (r.head.method == .GET and std.mem.eql(u8, path, "/")) {
                _ = handleRoot(&s) catch {};
                continue;
            }
            if (r.head.method == .POST and std.mem.eql(u8, path, "/research/start")) {
                _ = handleStart(&r, &s, providers) catch {};
                continue;
            }
            if (r.head.method == .GET and std.mem.startsWith(u8, path, "/research/status/")) {
                _ = handleStatus(&r, &s) catch {};
                continue;
            }
            if (r.head.method == .GET and std.mem.startsWith(u8, path, "/research/stream/")) {
                _ = handleSSE(&r, &s) catch {};
                continue;
            }
            if (r.head.method == .GET and std.mem.startsWith(u8, path, "/download/") and std.mem.endsWith(u8, path, ".zip")) {
                _ = handleDownload(&r, &s) catch {};
                continue;
            }
            s.status = .not_found;
            _ = s.do() catch {};
        } else break;
    }
}
