Az alábbi egyetlen shell script a teljes jadedlight appot nulláról felépíti Repliten is: létrehozza a Zig backend projektet (build.zig, src/main.zig), a frontend index.html-t, beállít egy .replit futtatási profilt, majd lefordítja és elindítja a szervert a környezeti változók használatával. Futtatás: mentsd setup_jadedlight.sh néven, tedd futtathatóvá (chmod +x setup_jadedlight.sh), majd ./setup_jadedlight.sh.

```bash
#!/usr/bin/env bash
set -euo pipefail

APP_NAME="jadedlight"

if ! command -v zig >/dev/null 2>&1; then
  echo "Zig nem található a PATH-ban. Repliten a nix támogatás miatt ez automatikusan települ a .replit és replit.nix alapján."
fi

mkdir -p src

cat > replit.nix <<'EOF'
{ pkgs }: {
  deps = [
    pkgs.zig
    pkgs.cacert
  ];
}
EOF

cat > .replit <<'EOF'
run = "zig build run"
EOF

cat > build.zig <<'EOF'
const std = @import("std");

pub fn build(b: *std.Build) void {
    const mode = b.standardOptimizeOption(.{});
    const target = b.standardTargetOptions(.{});
    const exe = b.addExecutable(.{
        .name = "jadedlight",
        .root_source_file = .{ .path = "src/main.zig" },
        .target = target,
        .optimize = mode,
    });
    exe.linkSystemLibrary("ssl");
    exe.linkSystemLibrary("crypto");
    exe.linkLibC();
    b.installArtifact(exe);

    const run_step = b.addRunArtifact(exe);
    if (b.args) |args| run_step.addArgs(args);
    const run_cmd = b.step("run", "Run jadedlight");
    run_cmd.dependOn(&run_step.step);
}
EOF

cat > src/main.zig <<'EOF'
const std = @import("std");

const Header = std.http.Header;
const Request = std.http.Server.Request;
const Response = std.http.Server.Response;

const JobState = struct { status: []const u8, progress: u8, started_at: i64, finished_at: i64, queries_count: usize, urls_count: usize };
const JobResult = struct { report: []u8, sources_json: []u8 };
const Job = struct { id: []const u8, state: JobState, result: ?JobResult };

const CerebrasCfg = struct { api_key: []const u8 };
const OpenAIcfg = struct { api_key: []const u8 };
const AnthropicCfg = struct { api_key: []const u8 };
const GeminiCfg = struct { api_key: []const u8 };
const XAIcfg = struct { api_key: []const u8 };
const ExaCfg = struct { api_key: []const u8 };

const Providers = struct {
    cerebras: ?CerebrasCfg,
    openai: ?OpenAIcfg,
    anthropic: ?AnthropicCfg,
