    if (prov.openai) |oai| { const o = openaiChat(oai, "gpt-5", msgs, 1800, 0.3, 0.5) catch null; if (o) |x| { _ = merged.appendSlice(x) catch {}; _ = merged.appendSlice("\n\n") catch {}; galloc.free(x); } }
