fn composeReport(prov: Providers, outline: [][]const u8, summaries: [][]const u8, target_chars: usize) []u8 {
    var seed = std.ArrayList(u8).init(galloc);
    for (outline) |s| { _ = seed.appendSlice("- ") catch {}; _ = seed.appendSlice(s) catch {}; _ = seed.appendSlice("\n") catch {}; }
    _ = seed.appendSlice("\n") catch {}; for (summaries) |sm| { _ = seed.appendSlice("\n---\n\n") catch {}; _ = seed.appendSlice(sm) catch {}; }
    const sys = "Compose a comprehensive research report from provided section plans and evidence summaries. Use academic tone, headings, tables, and references. Do not repeat. Maintain continuity.";
    var msgs = messagesJsonSystemUser(galloc, sys, seed.items) catch return seed.toOwnedSlice() catch seed.items; defer galloc.free(msgs);
    var full = std.ArrayList(u8).init(galloc);

    if (prov.cerebras) |cb| { const o = cerebrasChat(cb, "qwen-3-235b-a22b-thinking-2507", msgs, 32000, 0.5, 0.6, false) catch null; if (o) |x| { _ = full.appendSlice(x) catch {}; galloc.free(x); } }
    msgs = messagesJsonAppendAssistant(galloc, msgs, full.items) catch msgs;
    if (prov.cerebras) |cb2| { const o = cerebrasChat(cb2, "gpt-oss-120b", msgs, 48000, 0.6, 0.7, true) catch null; if (o) |x| { _ = full.appendSlice(x) catch {}; galloc.free(x); } }
    msgs = messagesJsonAppendAssistant(galloc, msgs, full.items) catch msgs;
    if (prov.cerebras) |cb3| { const o = cerebrasChat(cb3, "qwen-3-235b-a22b-instruct-2507", msgs, 20000, 0.3, 0.4, false) catch null; if (o) |x| { _ = full.appendSlice(x) catch {}; galloc.free(x); } }
    msgs = messagesJsonAppendAssistant(galloc, msgs, full.items) catch msgs;
    if (prov.openai) |oai| { const o = openaiChat(oai, "gpt-5", msgs, 36000, 0.4, 0.5) catch null; if (o) |x| { _ = full.appendSlice(x) catch {}; galloc.free(x); } }
    msgs = messagesJsonAppendAssistant(galloc, msgs, full.items) catch msgs;
    if (prov.anthropic) |a| { const o = anthropicChat(a, "claude-3-opus-20240229", sys, msgs, 36000, 0.4) catch null; if (o) |x| { _ = full.appendSlice(x) catch {}; galloc.free(x); } }
    msgs = messagesJsonAppendAssistant(galloc, msgs, full.items) catch msgs;
    if (prov.gemini) |g| { const map = geminiMapContents(galloc, sys, msgs) catch null; if (map) |mm| { const o = geminiGenerate(g, "models/gemini-2.5-pro", mm, 0.4, 0.5, 36000) catch null; if (o) |x| { _ = full.appendSlice(x) catch {}; galloc.free(x); } galloc.free(mm); } }
    msgs = messagesJsonAppendAssistant(galloc, msgs, full.items) catch msgs;
    if (prov.xai) |x| { const o = xaiChat(x, "grok-4", msgs, 36000, 0.5, 0.6) catch null; if (o) |xx| { _ = full.appendSlice(xx) catch {}; galloc.free(xx); } }

    while (full.items.len < target_chars) {
        const cont = continueTailPrompt(galloc, full.items, 2000) catch break; defer galloc.free(cont);
        var m2 = messagesJsonSystemUser(galloc, sys, cont) catch break; defer galloc.free(m2);
        if (prov.cerebras) |cb| { const o = cerebrasChat(cb, "gpt-oss-120b", m2, 36000, 0.5, 0.6, true) catch null; if (o) |x| { _ = full.appendSlice(x) catch {}; galloc.free(x); } } else break;
        msgs = messagesJsonAppendAssistant(galloc, msgs, full.items) catch msgs;
        if (full.items.len >= target_chars) break;
    }
    return full.toOwnedSlice() catch full.items;
}

