    res.status = .ok; try res.headers.append("content-type", "application/json; charset=utf-8"); try res.do();
    var buf = std.ArrayList(u8).init(galloc);
    try buf.appendSlice("{\"status\":\""); try buf.appendSlice(j.*.state.status);
    try buf.appendSlice("\",\"progress\":"); try buf.writer().print("{}", .{j.*.state.progress});
    try buf.appendSlice(",\"started_at\":"); try buf.writer().print("{}", .{j.*.state.started_at});
    try buf.appendSlice(",\"finished_at\":"); try buf.writer().print("{}", .{j.*.state.finished_at});
