fn handleDownload(req: *Request, res: *Response) !void {
    const path = req.head.target; const base = "/download/";
    if (!std.mem.startsWith(u8, path, base) or !std.mem.endsWith(u8, path, ".zip")) { res.status = .bad_request; try res.do(); return; }
    const job_id = path[base.len .. path.len - 4]; const j = jobs.get(job_id) orelse { res.status = .not_found; try res.do(); return; };
    if (j.*.result == null) { res.status = .not_found; try res.do(); return; }

    var mem = std.ArrayList<u8).init(galloc); var w = std.io.fixedBufferStream(try mem.addManyAsSlice(0, 0)); var aw = w.writer();
