fn researchRun(id: []const u8, prov: Providers, seed_text_in: []const u8, url_hint_in: ?[]const u8, target_chars: usize, max_sources: usize) void {
    var norm = seed_text_in; if (norm.len == 0 and url_hint_in) |u| { const fetched = httpGetText(u) catch ""; if (fetched.len > 0) norm = fetched; }
    if (norm.len == 0) { if (jobs.get(id)) |jp| { jp.*.state.status = "error"; jp.*.state.finished_at = nowTs(); } return; }
    if (norm.len > 20000) { const cp = galloc.alloc(u8, 20000) catch norm; if (cp.ptr != norm.ptr) { std.mem.copy(u8, cp, norm[0..20000]); norm = cp; } }

    var st = JobState{ .status = "starting", .progress = 0, .started_at = nowTs(), .finished_at = 0, .queries_count = 0, .urls_count = 0 };
    if (jobs.get(id)) |jp| jp.*.state = st;

    const deriv = deriveQueriesOutline(galloc, norm) catch { if (jobs.get(id)) |jp| { jp.*.state.status = "error"; jp.*.state.finished_at = nowTs(); } return; };
    st.status = "searching"; st.progress = 5; st.queries_count = deriv.queries.len; if (jobs.get(id)) |jp| jp.*.state = st;

    const urls = exaGather(prov, deriv.queries, 25, max_sources) catch std.ArrayList([]u8).init(galloc);
