            if (r.head.method == .POST and std.mem.eql(u8, path, "/research/start")) { _ = handleStart(&r, &s, providers) catch {}; continue; }
            if (r.head.method == .GET and std.mem.startsWith(u8, path, "/research/status/")) { _ = handleStatus(&r, &s) catch {}; continue; }
